import{_ as l,C as o,o as i,c as h,E as s,a3 as n,j as e,a as r}from"./chunks/framework.DCp5MHKK.js";const c="/versions/v0.19.28/screens/devices/euclid.png",p="/versions/v0.19.28/screens/devices/euclid-layer.png",g="/versions/v0.19.28/screens/devices/euclid-settings.png",u="/versions/v0.19.28/screens/devices/euclid_param_options_layer.png",m="/versions/v0.19.28/screens/devices/euclid_layer_chooser.png",R=JSON.parse('{"title":"Euclid","description":"","frontmatter":{"title":"Euclid","pageClass":"device-doc"},"headers":[],"relativePath":"devices/euclid.md","filePath":"devices/euclid.md"}'),y={name:"devices/euclid.md"},b={tabindex:"0"};function f(v,t,E,w,S,_){const d=o("DeviceHeading"),a=o("C");return i(),h("div",null,[s(d,{slug:"euclid",title:"Euclid"}),t[7]||(t[7]=n('<p>Euclidean rhythm generator</p><p><img src="'+c+'" alt="Euclid GRID" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Add <strong>Euclid</strong> after <strong>Clock</strong> for <strong>polyrhythmic Euclidean grids</strong>. Up to four layers can run in parallel with independent step counts, pulses, and rates.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Needs clock (internal or external). Euclid opens a <strong>two-tab device</strong> like <strong>Step Seq</strong> — not a long flat parameter list.</p></div><h2 id="grid-and-pencil" tabindex="-1">GRID and pencil <a class="header-anchor" href="#grid-and-pencil" aria-label="Permalink to &quot;GRID and pencil&quot;">​</a></h2><p>Euclid opens a full-width <strong>GRID</strong> of four layer rows. An open-left title shows the Euclid icon and <strong>R#/EUCLID</strong>. Folder tabs <strong>GRID</strong> and a <strong>pencil</strong> sit left of the BPM band. A small dim two-square mark between the tabs and the BPM is <strong>Select + Back</strong>.</p><table tabindex="0"><thead><tr><th>Control</th><th><strong>GRID</strong> (layers)</th><th><strong>Pencil</strong> (device settings)</th></tr></thead><tbody><tr><td>Encoder</td><td>Move focus across the four layer rows (including disabled layers)</td><td>Move between settings rows</td></tr><tr><td>Select</td><td>Does not enable or disable the layer. Use <strong>Enabled</strong> on the LAYER list</td><td>Latch <strong>sticky edit</strong> on Bypass. Tap Select again to keep the value; <strong>Back</strong> restores it and leaves Euclid</td></tr><tr><td>Hold Select + encoder</td><td>Nudge that layer’s <strong>Note</strong> on a continuous row; does not open a menu. After 200 ms the header shows a circle and square</td><td>Hold-edit Bypass (that hold does not latch sticky; same circle-and-square cue)</td></tr><tr><td>Select + Back</td><td>Switch to the <strong>pencil</strong></td><td>Switch back to <strong>GRID</strong></td></tr><tr><td>Long-press Select</td><td>The header <strong>Select square</strong> fills while you hold, then a left list titled <strong>LAYER 1</strong> (1-based) opens with that layer’s nine parameters</td><td>Open <strong>Options</strong> for Bypass</td></tr><tr><td>Back</td><td>Leave Euclid</td><td>Leave Euclid (does not return to GRID)</td></tr></tbody></table><p>Each layer is a strip of Step Seq pads that fills the row, even when that layer has only a few steps. Pulse steps are active pads; the rest are idle pads. Pads do not brighten for hover — the focused layer is marked with four corner ticks only. Pads do not show the layer note or a velocity bar. A 2-pixel-thick square <strong>playhead</strong> sits just inside the current step. Neighboring pads share one line so idle frames stay clean. Hold <strong>Select</strong> to change the <strong>note</strong>: the row keeps its outer box, inner walls and the playhead go away, and the note sits in the middle. Turn the encoder to change it; release Select to restore the grid. Disabled layers stay on screen and look dim. Enable or disable a layer from <strong>Enabled</strong> on its LAYER list.</p><p>With a <strong>LAYER</strong> list open on the left, tap <strong>Select</strong> on a value to latch sticky edit (same as Step Seq <strong>STEP</strong>). Tap <strong>Select</strong> again to keep the value and stay on the list. <strong>Back</strong> restores the value from when you entered and closes the list. <strong>Select + Back</strong> still switches <strong>GRID</strong> / <strong>pencil</strong>. <strong>Long-press Select</strong> on a LAYER-list row opens that row’s <strong>Options</strong> on the right.</p><p><img src="'+p+'" alt="Euclid LAYER list" class="screen"></p><p><img src="'+g+'" alt="Euclid settings" class="screen"></p><h2 id="choosing-a-layer-from-options" tabindex="-1">Choosing a layer from Options <a class="header-anchor" href="#choosing-a-layer-from-options" aria-label="Permalink to &quot;Choosing a layer from Options&quot;">​</a></h2><p>Long-press <strong>Select</strong> on the pencil or on a LAYER-list row for <strong>Options</strong>. <strong>LAYER</strong> is the last row and opens a four-tile chooser:</p><p><img src="'+u+'" alt="Euclid Options with the LAYER row" class="screen"></p><p><img src="'+m+'" alt="Euclid layer chooser" class="screen"></p>',16)),e("table",b,[t[6]||(t[6]=e("thead",null,[e("tr",null,[e("th",null,"Control"),e("th",null,"Does")])],-1)),e("tbody",null,[e("tr",null,[e("td",null,[s(a,{action:"encoder-turn"}),t[0]||(t[0]=r(" Encoder",-1))]),t[1]||(t[1]=e("td",null,[r("Move between "),e("strong",null,"LAYER 1 – 4")],-1))]),e("tr",null,[e("td",null,[s(a,{action:"select"}),t[2]||(t[2]=r(" Select",-1))]),t[3]||(t[3]=e("td",null,"Open that layer’s left parameter list",-1))]),e("tr",null,[e("td",null,[s(a,{action:"back"}),t[4]||(t[4]=r(" Back",-1))]),t[5]||(t[5]=e("td",null,"Keep the current layer",-1))])])]),t[8]||(t[8]=n('<p>The first rows of that <strong>Options</strong> menu are the same ones every device has, so giving a Euclid parameter an <a href="./../concepts/modulation">LFO</a> or a <a href="./../concepts/mapping">mapping</a> works exactly as it does elsewhere.</p><h2 id="settings-parameters" tabindex="-1">Settings parameters <a class="header-anchor" href="#settings-parameters" aria-label="Permalink to &quot;Settings parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Bypass</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr></tbody></table></div><h2 id="per-layer-parameters" tabindex="-1">Per-layer parameters <a class="header-anchor" href="#per-layer-parameters" aria-label="Permalink to &quot;Per-layer parameters&quot;">​</a></h2><p>These nine fields belong to the focused layer. Long-press Select on a layer in GRID to open them on the left.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Enabled</td><td>0 – 1</td><td>Turn this Euclidean layer on or off from the LAYER list.</td></tr><tr><td>Steps</td><td>1 – 16</td><td>Number of steps in the rhythm ring.</td></tr><tr><td>Pulses</td><td>1 – 16</td><td>Number of hits distributed across the steps.</td></tr><tr><td>Rate</td><td>0 – 6</td><td>Clock division for this layer.</td></tr><tr><td>Shift</td><td>0 – 15</td><td>Rotate the pattern within the ring.</td></tr><tr><td>Note</td><td>0 – 127</td><td>MIDI note emitted by hits on this layer (hold Select on GRID to see it on the row).</td></tr><tr><td>Channel</td><td>1 – 16</td><td>MIDI channel for this layer’s output.</td></tr><tr><td>Velocity</td><td>1 – 127</td><td>Note velocity for this layer.</td></tr><tr><td>Gate</td><td>0 – 200</td><td>Note length as percent of the step.</td></tr></tbody></table><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Off</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>On</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table><h3 id="enabled" tabindex="-1">Enabled <a class="header-anchor" href="#enabled" aria-label="Permalink to &quot;Enabled&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Off</td><td>This layer does not emit notes. The GRID row stays visible and dim.</td></tr><tr><td style="text-align:right;">1</td><td>On</td><td>This layer runs its Euclidean pattern.</td></tr></tbody></table>',11))])}const x=l(y,[["render",f]]);export{R as __pageData,x as default};
